sys_script.script:
(function executeRule(current, previous) {
    var proj = new GlideRecord('x_1850489_premiu_0_project');
    proj.initialize();
    proj.setValue('short_description', 'Project: ' + current.getValue('short_description'));
    proj.setValue('source_demand', current.getUniqueValue());
    proj.setValue('project_phase', 'initiation');
    proj.setValue('budget', current.getValue('estimated_cost'));
    proj.setValue('planned_start', current.getValue('requested_start'));
    proj.setValue('planned_end', current.getValue('requested_end'));
    proj.setValue('assigned_to', current.getValue('assigned_to'));
    proj.setValue('state', '1');
    proj.setValue('description', 'Auto-generated from approved demand: ' + current.getValue('number'));
    proj.insert();
})(current, previous);
